/* Destination selector shares the existing city/country catalogue. GPS is never simulated. */
(function(root){'use strict';
 let active=false,tab='domestic',category='推荐',query='',geo={state:'idle'},generation=0,busy=false;
 const provinceRows={'直辖市':['北京','上海','天津','重庆'],'港澳台':['香港','澳门','台北'],'海南':['三亚','海口'],'浙江':['杭州','宁波','舟山','安吉'],'广东':['广州','深圳'],'江苏':['苏州','南京','扬州','常州'],'山东':['青岛','济南'],'辽宁':['沈阳','大连'],'福建':['厦门','福州','泉州'],'吉林':['长春'],'黑龙江':['哈尔滨'],'四川':['成都'],'陕西':['西安'],'湖北':['武汉'],'湖南':['长沙','张家界'],'江西':['南昌'],'云南':['昆明','丽江','大理'],'广西':['南宁','桂林'],'河南':['郑州'],'安徽':['合肥'],'河北':['石家庄'],'山西':['太原'],'贵州':['贵阳'],'青海':['西宁'],'宁夏':['银川'],'甘肃':['兰州'],'内蒙古':['呼和浩特'],'西藏':['拉萨'],'新疆':['乌鲁木齐']};
 const pics={'杭州':'hangzhou.jpg','南京':'nanjing.jpg','北京':'beijing.jpg','上海':'shanghai.jpg','苏州':'suzhou.jpg','苏黎世':'zurich.jpg'};
 const normal=v=>NorthHotelData.normalize(v);
 const account=()=>typeof actId==='function'?String(actId()||'main'):'main';
 function state(){const t=tvInit();t.guideAccounts=t.guideAccounts||{};const id=account();return t.guideAccounts[id]||(t.guideAccounts[id]={selected:{name:'上海',country:'中国'},history:[]});}
 function rows(){const cities=NorthHotelData.cities().map(c=>({...c,type:'city'})),names=new Set(cities.map(c=>c.name));NorthHotelData.countries.forEach(c=>{if(!names.has(c[0]))cities.push({name:c[0],country:c[0],region:c[3],aliases:[c[1],c[2]],type:'country'});});return cities;}
 function domestic(c){return c.country==='中国';}
 function categories(){return tab==='domestic'?['推荐','热门',...Object.keys(provinceRows)]:['推荐','国家／地区','亚洲','欧洲','非洲','北美洲','南美洲','大洋洲','太平洋岛屿'];}
 function match(q,c){if(Object.entries(provinceRows).some(([p,a])=>(normal(p).includes(q)||normal(p+'省')===q)&&a.includes(c.name)))return true;return normal(c.name).includes(q)||normal(c.country).includes(q)||(c.aliases||[]).some(a=>normal(a).includes(q));}
 function list(){let a=rows().filter(c=>tab==='domestic'?domestic(c):!domestic(c));if(query)return rows().filter(c=>match(normal(query),c)).sort((x,y)=>(x.type==='country'?0:1)-(y.type==='country'?0:1));if(category==='国家／地区')return a.filter(c=>c.type==='country'||c.name===c.country);if(category==='推荐'||category==='热门'){const popular=tab==='domestic'?['杭州','苏州','舟山','南京','北京','上海','广州','深圳','成都','重庆','香港','台北']:['巴厘岛','吉隆坡','新加坡','巴黎','伦敦','纽约','东京','普吉岛','罗马','墨尔本','苏黎世','首尔'];return popular.map(n=>a.find(c=>c.name===n)).filter(Boolean);}if(tab==='domestic')return a.filter(c=>(provinceRows[category]||[]).includes(c.name));const region={北美洲:'北美',南美洲:'南美'}[category]||category;return a.filter(c=>c.region===region);}
 function open(){active=true;query='';tab=state().selected.country==='中国'?'domestic':'overseas';category='推荐';render();autoLocate();}
 function back(){active=false;render();}
 function deactivate(){active=false;}
 function choose(name){let c=rows().find(c=>c.name===name);if(!c&&geo.state==='done'&&geo.city===name)c={name,country:geo.country||'',region:'当前位置'};if(!c)return;const s=state();s.selected={name:c.name,country:c.country,type:c.type||'city'};s.history=[{name:c.name,country:c.country},...(s.history||[]).filter(h=>h.name!==c.name)].slice(0,12);save();active=false;render();}
 function clear(){state().history=[];save();paint();}
 function setTab(v){if(!['domestic','overseas'].includes(v))return;tab=v;category='推荐';paint();}
 function setCategory(v){if(!categories().includes(v))return;category=v;paint();}
 function input(v){query=String(v||'').slice(0,80);if(query){const hits=rows().filter(c=>match(normal(query),c));if(hits.length&&hits.every(domestic))tab='domestic';else if(hits.length&&hits.every(c=>!domestic(c)))tab='overseas';}paint();}
 function paint(){if(!active)return;const host=document.querySelector('.ctd-app');if(!host)return;host.querySelectorAll('[data-region-tab]').forEach(e=>e.classList.toggle('selected',e.dataset.regionTab===tab));paintBody();}
 function paintBody(){const side=document.getElementById('ctdSidebar'),body=document.getElementById('ctdBody');if(side)side.innerHTML=sidebar();if(body){body.innerHTML=content();body.scrollTop=0;}}
 function card(c,i){const photo=typeof NorthDestinationPhotos!=='undefined'?NorthDestinationPhotos.get(c.name):null;const src=photo?.src||pics[c.name];return '<button class="ctd-card" data-destination="'+esc(c.name)+'" onclick="NorthTravelRegions.choose(this.dataset.destination)"><div class="ctd-photo ctd-skin-'+(i%5)+'">'+(src?'<img src="assets/travel-home/'+src+'" alt="'+esc(photo?.representative?c.name+' · '+photo.representative:c.name)+'" loading="lazy" decoding="async" width="320" height="240" onerror="this.hidden=true">':'<span>'+esc(c.name)+'</span><svg viewBox="0 0 80 40" aria-hidden="true"><path d="M0 40 22 14 38 29 58 7 80 40Z" fill="currentColor"/></svg>')+'</div><span>'+esc(c.name)+'</span></button>';}
 function locationHTML(){const good=geo.state==='done',label=good?geo.city:geo.state==='loading'?'正在定位…':geo.state==='error'?'定位未完成':'定位当前位置';return '<section class="ctd-location"><h2>当前位置</h2><div class="ctd-locate-row"><button '+(busy?'disabled':'')+' onclick="NorthTravelRegions.'+(good?'chooseCurrent()':'locate()')+'"><span class="ctd-location-pin">'+NorthTravelHome.icon('pin')+'</span><b>'+esc(label)+'</b></button><button class="ctd-refresh" aria-label="刷新当前位置" onclick="NorthTravelRegions.locate()" '+(busy?'disabled':'')+'>↻</button></div><p>'+esc(good?geo.address+(geo.accuracy?' · 定位精度约'+Math.round(geo.accuracy)+'米':''):geo.state==='error'?geo.error:'点击刷新获取设备真实位置')+'</p></section>';}
 function chooseCurrent(){if(geo.state==='done')choose(geo.city);}
 function sidebar(){return categories().map(c=>'<button class="'+(category===c?'selected':'')+'" data-category="'+esc(c)+'" onclick="NorthTravelRegions.setCategory(this.dataset.category)">'+esc(c)+'</button>').join('');}
 function content(){const a=list(),history=(state().history||[]).filter(h=>tab==='domestic'?h.country==='中国':h.country!=='中国');const recommend=!query&&category==='推荐';return (recommend&&tab==='overseas'?'<section class="ctd-country-shortcuts"><h2>选择国家／地区</h2><div>'+['美国','日本','韩国','英国','法国','澳大利亚'].map(n=>'<button data-destination="'+n+'" onclick="NorthTravelRegions.choose(this.dataset.destination)">'+n+'</button>').join('')+'<button onclick="NorthTravelRegions.setCategory(\'国家／地区\')">全部国家 ›</button></div></section>':'')+(recommend&&tab==='domestic'?locationHTML():'')+(recommend?'<section class="ctd-history"><div><h2>历史选择</h2><button onclick="NorthTravelRegions.clear()">清除历史</button></div>'+(history.length?'<div class="ctd-history-tags">'+history.map(h=>'<button data-destination="'+esc(h.name)+'" onclick="NorthTravelRegions.choose(this.dataset.destination)">'+esc(h.name)+'</button>').join('')+'</div>':'<p class="ctd-muted">暂无历史选择</p>')+'</section>':'')+'<section><h2>'+esc(query?'搜索结果':recommend?(tab==='domestic'?'精选目的地':'热门目的地'):category)+'</h2><div class="ctd-grid">'+a.map(card).join('')+'</div>'+(!a.length?'<p class="ctd-muted">没有找到匹配的目的地，请换个名称或搜索国家。</p>':'')+'</section>'+(query?'<p class="ctd-muted">共 '+a.length+' 个匹配目的地</p>':'');}
 function page(){return '<div class="ctd-app"><header class="ctd-header"><button aria-label="返回攻略页面" onclick="NorthTravelRegions.back()"><svg viewBox="0 0 24 24"><path d="m15 4-8 8 8 8"/></svg></button><form onsubmit="event.preventDefault()">'+NorthTravelHome.icon('search')+'<input id="ctdSearch" aria-label="搜索目的地" placeholder="搜索目的地" value="'+esc(query)+'" oninput="NorthTravelRegions.input(this.value)" autocomplete="off"></form></header><nav class="ctd-tabs"><button data-region-tab="domestic" class="'+(tab==='domestic'?'selected':'')+'" onclick="NorthTravelRegions.setTab(\'domestic\')">境内 · 港澳台</button><button data-region-tab="overseas" class="'+(tab==='overseas'?'selected':'')+'" onclick="NorthTravelRegions.setTab(\'overseas\')">境外</button></nav><div class="ctd-layout"><aside id="ctdSidebar">'+sidebar()+'</aside><main id="ctdBody" class="travel-scroll">'+content()+'</main></div></div>';}
 function updateLocation(){if(active&&tab==='domestic'&&category==='推荐'&&!query){const node=document.querySelector('.ctd-location');if(node){const d=document.createElement('div');d.innerHTML=locationHTML();node.replaceWith(d.firstElementChild);}}}
 async function autoLocate(){if(geo.state==='done'&&Date.now()-geo.ts<60000)return;try{if(navigator.permissions&&(await navigator.permissions.query({name:'geolocation'})).state==='granted')locate();}catch(_){}}
 async function locate(){if(busy)return;busy=true;const ticket=++generation;geo={state:'loading'};updateLocation();let coords;
  try{if(root.__SMALL_PHONE_PRIVATE__&&root.SmallPhoneNative?.request){const n=await root.SmallPhoneNative.request('location.current');const v=n&&n.result||n;if(v&&Number.isFinite(+v.latitude)&&Number.isFinite(+v.longitude)&&v.timestamp&&+v.accuracy>=0&&Date.now()-v.timestamp>=-5000&&Date.now()-v.timestamp<60000)coords={latitude:+v.latitude,longitude:+v.longitude,accuracy:+v.accuracy||0};}
   if(!coords){if(!navigator.geolocation)throw new Error('设备不支持定位');coords=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve(p.coords),e=>reject(new Error(e.code===1?'未授权定位，请在系统或浏览器设置中允许位置访问':e.code===3?'定位超时，请点击刷新重试':'无法获取设备位置，请检查定位服务')),{enableHighAccuracy:true,timeout:10000,maximumAge:0}));}
   if(!Number.isFinite(coords.latitude)||!Number.isFinite(coords.longitude)||Math.abs(coords.latitude)>90||Math.abs(coords.longitude)>180)throw new Error('设备返回了无效坐标');
   const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);let g;try{const r=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+encodeURIComponent(coords.latitude)+'&longitude='+encodeURIComponent(coords.longitude)+'&localityLanguage=zh',{signal:ctrl.signal});if(!r.ok)throw new Error('位置名称服务暂时不可用');g=await r.json();}finally{clearTimeout(timer);}
   const city=String(g.city||g.locality||g.principalSubdivision||'').trim();if(!city)throw new Error('已取得设备坐标，但未获取到城市名称，请重试');
   const country=(NorthHotelData.countries.find(c=>c[2]===g.countryCode)||[])[0]||String(g.countryName||'');const known=NorthHotelData.cities().find(c=>c.country===country&&[c.name,...c.aliases].some(n=>normal(n)===normal(city.replace(/市$/,''))));
   geo={state:'done',city:known?known.name:city,country,address:[g.countryName,g.principalSubdivision,g.city,g.locality].filter((x,i,a)=>x&&a.indexOf(x)===i).join(' · '),accuracy:coords.accuracy,ts:Date.now()};
  }catch(e){geo={state:'error',error:e.name==='AbortError'?'位置名称查询超时，请重试':String(e.message||'定位失败')};}finally{if(ticket===generation){busy=false;updateLocation();}}
 }
 root.NorthTravelRegions={active:()=>active,deactivate,open,back,render:page,choose,clear,setTab,setCategory,input,locate,chooseCurrent,selected:()=>state().selected,catalogue:rows};
})(window);
